<div class="page-head"><div><span class="eyebrow">Access Control</span><h1>Users</h1><p>Create users, manage access, and securely reset passwords.</p></div><a class="btn btn-primary" href="<?=url('admin-user-form')?>">+ Add User</a></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Business</th><th>Provider KPI</th><th>Status</th><th>Last Login</th><th data-no-sort>Actions</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['name'])?></strong><small class="block"><?=e($u['email'])?></small><?php if(!empty($u['must_change_password'])):?><small class="password-state">Password change required</small><?php endif;?></td><td><?=e(ucwords(str_replace('_',' ',$u['role'])))?></td><td><?=e($u['business_name']?:'Platform-wide')?></td><td><?=e($u['role']==='business_user'?ucwords(str_replace('_',' ',(string)($u['provider_kpi_role']??'none'))):'Platform-wide')?></td><td><span class="status status-<?=e($u['status'])?>"><?=e(ucfirst($u['status']))?></span></td><td><?=e($u['last_login_at']?reporting_us_date($u['last_login_at'],true):'Never')?></td><td><div class="table-actions"><a class="btn btn-small btn-secondary" href="<?=url('admin-user-form',['id'=>$u['id']])?>">Edit</a><a class="btn btn-small btn-primary" href="<?=url('admin-user-password',['id'=>$u['id']])?>">Reset Password</a></div></td></tr><?php endforeach;?></tbody></table></div></section>
